// ==================== Helper Functions ====================
bool approx_equal(float a, float b, float epsilon = 0.0001f) { return std::abs(a - b) < epsilon; }

bool vec3_approx_equal(const glm::vec3& a, const glm::vec3& b, float epsilon = 0.0001f) {
    return approx_equal(a.x, b.x, epsilon) && approx_equal(a.y, b.y, epsilon) && approx_equal(a.z, b.z, epsilon);
}

bool quat_approx_equal(const glm::quat& a, const glm::quat& b, float epsilon = 0.0001f) {
    bool same = approx_equal(a.w, b.w, epsilon) && approx_equal(a.x, b.x, epsilon) && approx_equal(a.y, b.y, epsilon) && approx_equal(a.z, b.z, epsilon);

    bool opposite = approx_equal(a.w, -b.w, epsilon) && approx_equal(a.x, -b.x, epsilon) && approx_equal(a.y, -b.y, epsilon) && approx_equal(a.z, -b.z, epsilon);

    return same || opposite;
}

