// ==================== Local Position Tests ====================
TEST_F(TransformTest, LocalPositionGetterSetter) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Default position
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), glm::vec3(0.0f)));

    // Set and get position
    glm::vec3 pos(1.0f, 2.0f, 3.0f);
    transform.set_local_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), pos));

    // Edge case: negative values
    pos = glm::vec3(-5.0f, -10.0f, -15.0f);
    transform.set_local_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), pos));

    // Edge case: very large values
    pos = glm::vec3(1000000.0f, 2000000.0f, 3000000.0f);
    transform.set_local_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), pos));

    // Edge case: very small values
    pos = glm::vec3(0.0001f, 0.0002f, 0.0003f);
    transform.set_local_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), pos));
}

// ==================== Local Rotation Tests ====================
TEST_F(TransformTest, LocalRotationQuaternion) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Default rotation (identity)
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), glm::quat(1.0f, 0.0f, 0.0f, 0.0f)));

    // Set rotation
    glm::quat rot = glm::angleAxis(glm::radians(45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    transform.set_local_rotation(rot);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), rot));

    // Edge case: 180 degree rotation
    rot = glm::angleAxis(glm::radians(180.0f), glm::vec3(1.0f, 0.0f, 0.0f));
    transform.set_local_rotation(rot);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), rot));

    // Edge case: identity quaternion
    rot = glm::quat(1.0f, 0.0f, 0.0f, 0.0f);
    transform.set_local_rotation(rot);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), rot));
}

TEST_F(TransformTest, LocalRotationEuler) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Zero euler angles
    glm::vec3 euler(0.0f, 0.0f, 0.0f);
    transform.set_local_rotation(euler);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), glm::quat(1.0f, 0.0f, 0.0f, 0.0f)));

    // Set euler angles (45 degrees on each axis)
    euler = glm::vec3(glm::radians(45.0f), glm::radians(45.0f), glm::radians(45.0f));
    transform.set_local_rotation(euler);
    auto expected = glm::quat(euler);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));

    // Edge case: 90 degree pitch (potential gimbal lock)
    euler = glm::vec3(glm::radians(90.0f), 0.0f, 0.0f);
    transform.set_local_rotation(euler);
    expected = glm::quat(euler);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));

    // Edge case: negative angles
    euler = glm::vec3(glm::radians(-30.0f), glm::radians(-60.0f), glm::radians(-90.0f));
    transform.set_local_rotation(euler);
    expected = glm::quat(euler);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));
}

TEST_F(TransformTest, LocalRotationAxisAngle) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // 90 degrees around Y axis
    glm::vec3 axis(0.0f, 1.0f, 0.0f);
    float angle = glm::radians(90.0f);
    transform.set_local_rotation(axis, angle);
    glm::quat expected = glm::angleAxis(angle, axis);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));

    // Edge case: zero angle
    transform.set_local_rotation(axis, 0.0f);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), glm::quat(1.0f, 0.0f, 0.0f, 0.0f)));

    // Edge case: 360 degrees (should be identity)
    transform.set_local_rotation(axis, glm::radians(360.0f));
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), glm::quat(1.0f, 0.0f, 0.0f, 0.0f)));

    // Edge case: arbitrary axis
    axis = glm::normalize(glm::vec3(1.0f, 2.0f, 3.0f));
    angle = glm::radians(120.0f);
    transform.set_local_rotation(axis, angle);
    expected = glm::angleAxis(angle, axis);
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));
}

