// ==================== World Position Tests ====================
TEST_F(TransformTest, WorldPositionNoParent) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Without parent, world position should equal local position
    glm::vec3 pos(5.0f, 10.0f, 15.0f);
    transform.set_local_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_world_position(), pos));

    // Set world position directly
    pos = glm::vec3(20.0f, 25.0f, 30.0f);
    transform.set_world_position(pos);
    EXPECT_TRUE(vec3_approx_equal(transform.get_world_position(), pos));
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), pos));
}

TEST_F(TransformTest, WorldPositionWithParent) {
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child_entity = tmt::engine.ecs.create_entity();

    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

    // Set parent position
    parent.set_local_position(glm::vec3(10.0f, 20.0f, 30.0f));

    // Set child as child of parent
    child.set_parent(parent_entity);

    // Set child local position
    child.set_local_position(glm::vec3(5.0f, 5.0f, 5.0f));

    // World position should be parent + child
    glm::vec3 expected_world = glm::vec3(15.0f, 25.0f, 35.0f);
    EXPECT_TRUE(vec3_approx_equal(child.get_world_position(), expected_world));

    // Set world position of child
    child.set_world_position(glm::vec3(100.0f, 100.0f, 100.0f));
    EXPECT_TRUE(vec3_approx_equal(child.get_world_position(), glm::vec3(100.0f, 100.0f, 100.0f)));
}

