TEST_F(TransformTest, WorldRotationNoParent) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Without parent, world rotation should equal local rotation
    glm::quat rot = glm::angleAxis(glm::radians(45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    transform.set_local_rotation(rot);
    EXPECT_TRUE(quat_approx_equal(transform.get_world_rotation(), rot));

    // Set world rotation using euler angles
    glm::vec3 euler(glm::radians(30.0f), glm::radians(60.0f), glm::radians(90.0f));
    transform.set_world_rotation(euler);
    auto expected = glm::quat(euler);
    EXPECT_TRUE(quat_approx_equal(transform.get_world_rotation(), expected));

    // Set world rotation using axis-angle
    glm::vec3 axis = glm::normalize(glm::vec3(1.0f, 1.0f, 1.0f));
    float angle = glm::radians(60.0f);
    transform.set_world_rotation(axis, angle);
    expected = glm::angleAxis(angle, axis);
    EXPECT_TRUE(quat_approx_equal(transform.get_world_rotation(), expected));
}

