// ==================== Transform Operations Tests ====================
TEST_F(TransformTest, Translate) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    transform.set_local_position(glm::vec3(10.0f, 10.0f, 10.0f));

    // Translate by delta
    transform.translate(glm::vec3(5.0f, -3.0f, 2.0f));
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), glm::vec3(15.0f, 7.0f, 12.0f)));

    // Translate by zero
    transform.translate(glm::vec3(0.0f));
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), glm::vec3(15.0f, 7.0f, 12.0f)));

    // Multiple translations
    transform.translate(glm::vec3(1.0f, 1.0f, 1.0f));
    transform.translate(glm::vec3(2.0f, 2.0f, 2.0f));
    EXPECT_TRUE(vec3_approx_equal(transform.get_local_position(), glm::vec3(18.0f, 10.0f, 15.0f)));
}

TEST_F(TransformTest, RotateLocalQuaternion) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Start with identity
    glm::quat initial = glm::angleAxis(glm::radians(45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    transform.set_local_rotation(initial);

    // Rotate by additional amount
    glm::quat delta = glm::angleAxis(glm::radians(45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    transform.rotate_local(delta);

    glm::quat expected = delta * initial;
    EXPECT_TRUE(quat_approx_equal(transform.get_local_rotation(), expected));
}

TEST_F(TransformTest, RotateLocalEuler) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    glm::quat initial = glm::angleAxis(glm::radians(30.0f), glm::vec3(1.0f, 0.0f, 0.0f));
    transform.set_local_rotation(initial);

    // Rotate by euler angles
    glm::vec3 euler_delta(glm::radians(15.0f), glm::radians(30.0f), glm::radians(45.0f));
    transform.rotate_local(euler_delta);

    auto delta = glm::quat(euler_delta);
    auto expected = initial * delta;
    auto current = transform.get_local_rotation();
    EXPECT_TRUE(quat_approx_equal(current, expected));
}

