// ==================== Direction Vector Tests ====================
TEST_F(TransformTest, ForwardUpRightVectors) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Identity rotation
    transform.set_local_rotation(glm::quat(1.0f, 0.0f, 0.0f, 0.0f));

    glm::vec3 forward = transform.get_forward();
    glm::vec3 up = transform.get_up();
    glm::vec3 right = transform.get_right();

    EXPECT_TRUE(vec3_approx_equal(forward, glm::vec3(0.0f, 0.0f, -1.0f), 0.01f));
    EXPECT_TRUE(vec3_approx_equal(up, glm::vec3(0.0f, 1.0f, 0.0f), 0.01f));
    EXPECT_TRUE(vec3_approx_equal(right, glm::vec3(1.0f, 0.0f, 0.0f), 0.01f));

    // Rotate 90 degrees around Y axis
    transform.set_local_rotation(glm::angleAxis(glm::radians(90.0f), glm::vec3(0.0f, 1.0f, 0.0f)));
    forward = transform.get_forward();
    right = transform.get_right();

    EXPECT_TRUE(vec3_approx_equal(forward, glm::vec3(-1.0f, 0.0f, 0.0f), 0.01f));
    EXPECT_TRUE(vec3_approx_equal(right, glm::vec3(0.0f, 0.0f, -1.0f), 0.01f));

    // Rotate 90 degrees around X axis
    transform.set_local_rotation(glm::angleAxis(glm::radians(90.0f), glm::vec3(1.0f, 0.0f, 0.0f)));
    forward = transform.get_forward();
    up = transform.get_up();

    EXPECT_TRUE(vec3_approx_equal(forward, glm::vec3(0.0f, 1.0f, 0.0f), 0.01f));
    EXPECT_TRUE(vec3_approx_equal(up, glm::vec3(0.0f, 0.0f, 1.0f), 0.01f));
}

TEST_F(TransformTest, LookAt) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    transform.set_local_position(glm::vec3(0.0f, 0.0f, 0.0f));

    // Look at target directly ahead
    glm::vec3 target(0.0f, 0.0f, -10.0f);
    glm::vec3 up(0.0f, 1.0f, 0.0f);
    transform.look_at(target, up);

    glm::vec3 forward = transform.get_forward();
    glm::vec3 expected_dir = glm::normalize(target - transform.get_local_position());
    EXPECT_TRUE(vec3_approx_equal(forward, expected_dir, 0.01f));

    // Look at target to the right
    target = glm::vec3(10.0f, 0.0f, 0.0f);
    transform.look_at(target, up);
    forward = transform.get_forward();
    expected_dir = glm::normalize(target - transform.get_local_position());
    EXPECT_TRUE(vec3_approx_equal(forward, expected_dir, 0.01f));

    // Look at target above
    target = glm::vec3(0.0f, 10.0f, 0.0f);
    transform.look_at(target, glm::vec3(0.0f, 0.0f, 1.0f));
    forward = transform.get_forward();
    expected_dir = glm::normalize(target - transform.get_local_position());
    EXPECT_TRUE(vec3_approx_equal(forward, expected_dir, 0.01f));
}

// ==================== Matrix Tests ====================
TEST_F(TransformTest, WorldMatrix) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Set TRS values
    glm::vec3 pos(1.0f, 2.0f, 3.0f);
    glm::quat rot = glm::angleAxis(glm::radians(45.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    glm::vec3 scale(2.0f, 3.0f, 4.0f);

    transform.set_local_position(pos);
    transform.set_local_rotation(rot);
    transform.set_local_scale(scale);

    // Get world matrix
    glm::mat4 world = transform.get_world_matrix();

    // Manually construct expected matrix
    glm::mat4 expected(1.0f);
    expected = glm::translate(expected, pos);
    expected = expected * glm::mat4_cast(rot);
    expected = glm::scale(expected, scale);

    // Compare matrices (element by element)
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            EXPECT_TRUE(approx_equal(world[i][j], expected[i][j], 0.01f));
        }
    }
}

TEST_F(TransformTest, SetWorldMatrix) {
    tmt::Entity entity = tmt::engine.ecs.create_entity();
    auto& transform = tmt::engine.ecs.add_component<tmt::Transform>(entity);

    // Create a matrix manually
    glm::mat4 matrix(1.0f);
    matrix = glm::translate(matrix, glm::vec3(5.0f, 10.0f, 15.0f));
    matrix = glm::rotate(matrix, glm::radians(90.0f), glm::vec3(0.0f, 1.0f, 0.0f));
    matrix = glm::scale(matrix, glm::vec3(2.0f, 2.0f, 2.0f));

    // Set the world matrix
    transform.set_world_matrix(matrix);

    // Get it back and compare
    glm::mat4 result = transform.get_world_matrix();
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            EXPECT_TRUE(approx_equal(result[i][j], matrix[i][j], 0.01f));
        }
    }
}

// ==================== Hierarchy Tests ====================
TEST_F(TransformTest, ParentChildHierarchy) {
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child_entity = tmt::engine.ecs.create_entity();

    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

    // Initially no parent
    EXPECT_FALSE(child.has_parent());

    // Set parent
    child.set_parent(parent_entity);
    EXPECT_TRUE(child.has_parent());
    EXPECT_EQ(child.get_parent(), parent_entity);

    // Check parent's children list
    const auto& children = parent.get_children();
    EXPECT_EQ(children.size(), 1);
    EXPECT_EQ(children.count(child_entity), 1);

    // Clear parent
    child.clear_parent();
    EXPECT_FALSE(child.has_parent());
    EXPECT_TRUE(parent.get_children().empty());
}

TEST_F(TransformTest, MultiLevelHierarchy) {
    tmt::Entity grandparent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child_entity = tmt::engine.ecs.create_entity();

    auto& grandparent = tmt::engine.ecs.add_component<tmt::Transform>(grandparent_entity);
    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

    // Set up hierarchy: grandparent -> parent -> child
    parent.set_parent(grandparent_entity);
    child.set_parent(parent_entity);

    // Set positions
    grandparent.set_local_position(glm::vec3(10.0f, 0.0f, 0.0f));
    parent.set_local_position(glm::vec3(5.0f, 0.0f, 0.0f));
    child.set_local_position(glm::vec3(2.0f, 0.0f, 0.0f));

    // Check world positions
    EXPECT_TRUE(vec3_approx_equal(grandparent.get_world_position(), glm::vec3(10.0f, 0.0f, 0.0f)));
    EXPECT_TRUE(vec3_approx_equal(parent.get_world_position(), glm::vec3(15.0f, 0.0f, 0.0f)));
    EXPECT_TRUE(vec3_approx_equal(child.get_world_position(), glm::vec3(17.0f, 0.0f, 0.0f)));

    // Change grandparent position, should affect all
    grandparent.set_local_position(glm::vec3(0.0f, 0.0f, 0.0f));
    EXPECT_TRUE(vec3_approx_equal(parent.get_world_position(), glm::vec3(5.0f, 0.0f, 0.0f)));
    EXPECT_TRUE(vec3_approx_equal(child.get_world_position(), glm::vec3(7.0f, 0.0f, 0.0f)));
}

TEST_F(TransformTest, AddRemoveChildren) {
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child1_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child2_entity = tmt::engine.ecs.create_entity();

    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child1 = tmt::engine.ecs.add_component<tmt::Transform>(child1_entity);
    auto& child2 = tmt::engine.ecs.add_component<tmt::Transform>(child2_entity);

    // Add children manually
    parent.add_child(child1_entity);
    parent.add_child(child2_entity);

    EXPECT_EQ(parent.get_children().size(), 2);
    EXPECT_EQ(parent.get_children().count(child1_entity), 1);
    EXPECT_EQ(parent.get_children().count(child2_entity), 1);

    // Remove one child
    parent.remove_child(child1_entity);
    EXPECT_EQ(parent.get_children().size(), 1);
    EXPECT_EQ(parent.get_children().count(child1_entity), 0);
    EXPECT_EQ(parent.get_children().count(child2_entity), 1);

    // Remove non-existent child (should not crash)
    parent.remove_child(child1_entity);
    EXPECT_EQ(parent.get_children().size(), 1);

    // Remove last child
    parent.remove_child(child2_entity);
    EXPECT_TRUE(parent.get_children().empty());
}

TEST_F(TransformTest, HierarchyWithRotation) {
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child_entity = tmt::engine.ecs.create_entity();

    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

    child.set_parent(parent_entity);

    // Parent rotates 90 degrees around Y
    parent.set_local_rotation(glm::angleAxis(glm::radians(90.0f), glm::vec3(0.0f, 1.0f, 0.0f)));

    // Child at local position (10, 0, 0)
    child.set_local_position(glm::vec3(10.0f, 0.0f, 0.0f));

    // In world space, child should be at (0, 0, -10) due to parent rotation
    glm::vec3 world_pos = child.get_world_position();
    EXPECT_TRUE(vec3_approx_equal(world_pos, glm::vec3(0.0f, 0.0f, -10.0f), 0.01f));
}

TEST_F(TransformTest, HierarchyWithScale) {
    tmt::Entity parent_entity = tmt::engine.ecs.create_entity();
    tmt::Entity child_entity = tmt::engine.ecs.create_entity();

    auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
    auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

    child.set_parent(parent_entity);

    // Parent has scale of 2
    parent.set_local_scale(glm::vec3(2.0f));

    // Child has local scale of 3
    child.set_local_scale(glm::vec3(3.0f));

    // World scale should be 6 (2 * 3)
    glm::vec3 world_scale = child.get_world_scale();
    EXPECT_TRUE(vec3_approx_equal(world_scale, glm::vec3(6.0f), 0.01f));
}

